test("adding a problem from a list opens URL-only filters", () => {
  frontend.individualList = frontend.lists[0];
  render(<><ListPage /><LocationProbe /></>, { wrapper: createRouterWrapper("/lists") });

  fireEvent.click(screen.getByRole("button", { name: "Test list" }));
  fireEvent.click(screen.getByRole("button", { name: "Add Problem" }));

  const location = new URL(screen.getByTestId("location").textContent!, "https://example.test");
  expect(location.pathname).toBe(Path.PROBLEMS);
  const params = location.searchParams;
  expect(params.get(SearchKeys.ListId)).toBe("5");
  expect(params.get(SearchKeys.UseFilterStorage)).toBe("false");
});

// Generated by Codex and not thoroughly checked for correctness.
test("deep links restore selection, renames refresh it, and removed lists clear stale content", () => {
  const wrapper = createRouterWrapper("/lists?listId=5&keep=yes");
  const hook = renderHook(useListPage, { wrapper });
  expect(hook.result.current.activeList?.name).toBe("Test list");
  frontend.lists = [{ ...frontend.lists[0], name: "Renamed" }];
  hook.rerender();
  expect(hook.result.current.activeList?.name).toBe("Renamed");
  frontend.lists = [];
  hook.rerender();
  expect(hook.result.current.activeList).toBeUndefined();
});

// Generated by Codex and not thoroughly checked for correctness.
test("list selection follows Back and Forward and preserves unrelated parameters", () => {
  frontend.lists.push(createList({ id: 6, name: "Second" }));
  const wrapper = createRouterWrapper("/lists?listId=5&keep=yes");
  const hook = renderHook(() => ({ list: useListPage(), location: useLocation(), navigate: useNavigate() }), { wrapper });
  act(() => hook.result.current.list.listClicked("Second"));
  expect(hook.result.current.list.activeList?.id).toBe(6);
  expect(new URLSearchParams(hook.result.current.location.search).get("keep")).toBe("yes");
  act(() => { void hook.result.current.navigate(-1); });
  expect(hook.result.current.list.activeList?.id).toBe(5);
  act(() => { void hook.result.current.navigate(1); });
  expect(hook.result.current.list.activeList?.id).toBe(6);
});

